import { MakeLogicType, actions, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { BrandedSegmentEnumApi } from 'products/web_analytics/frontend/generated/api.schemas'

export type BrandedSegmentTab = 'overview' | 'rankings'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface contentAutopilotBrandedLogicValues {
    brandedSegment: BrandedSegmentEnumApi
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface contentAutopilotBrandedLogicActions {
    setBrandedSegment: (
        brandedSegment: BrandedSegmentEnumApi,
        tab: BrandedSegmentTab
    ) => {
        brandedSegment: BrandedSegmentEnumApi
        tab: BrandedSegmentTab
    }
}

export type contentAutopilotBrandedLogicType = MakeLogicType<
    contentAutopilotBrandedLogicValues,
    contentAutopilotBrandedLogicActions
>

/** Which prompts the Overview and Rankings tabs count, shared so both tabs show the same split. */
export const contentAutopilotBrandedLogic = kea<contentAutopilotBrandedLogicType>([
    path(['products', 'webAnalytics', 'contentAutopilot', 'contentAutopilotBrandedLogic']),
    actions({
        setBrandedSegment: (brandedSegment: BrandedSegmentEnumApi, tab: BrandedSegmentTab) => ({
            brandedSegment,
            tab,
        }),
    }),
    reducers({
        // Non-branded by default, because a prompt that names the brand almost always gets an answer that mentions it.
        // The web analytics scene owns this page's URL and rewrites it without extra params, so the choice is kept in
        // local storage instead of the URL.
        brandedSegment: [
            BrandedSegmentEnumApi.NonBranded as BrandedSegmentEnumApi,
            { persist: true },
            {
                setBrandedSegment: (_, { brandedSegment }) => brandedSegment,
            },
        ],
    }),
    listeners(() => ({
        setBrandedSegment: ({ brandedSegment, tab }) => {
            // pinned: analytics event name, renaming it breaks dashboards
            posthog.capture('web analytics content autopilot branded segment changed', {
                segment: brandedSegment,
                tab,
            })
        },
    })),
])
